import http from "node:http";

const PORT = Number(process.env.ONENODE_AGENT_PORT || 18910);
const HOST = process.env.ONENODE_AGENT_HOST || "127.0.0.1";
const MODE = process.env.ONENODE_AGENT_MODE || "mock";
const CLAW_BASE_URL = (process.env.CLAW_BASE_URL || "http://127.0.0.1:18889").replace(/\/+$/, "");
const LOCAL_AGENT_BASE_URL = (process.env.LOCAL_AGENT_BASE_URL || process.env.CLAW_BASE_URL || "http://127.0.0.1:18889").replace(/\/+$/, "");

const profile = {
  agentId: "local_agent_bridge",
  name: MODE === "claw" ? "Claw Bridge Agent" : MODE === "agent" ? "Local Agent Bridge" : "OneNode Local Agent",
  status: "online",
  mode: MODE,
  skills: ["social", "relationship-suggest", "message-draft", "wallet-check", "research"],
  endpoint: `http://${HOST}:${PORT}`,
};

const server = http.createServer(async (request, response) => {
  setCorsHeaders(response);

  if (request.method === "OPTIONS") {
    response.writeHead(204);
    response.end();
    return;
  }

  try {
    const url = new URL(request.url || "/", `http://${request.headers.host}`);

    if (request.method === "GET" && url.pathname === "/health") {
      sendJson(response, { ok: true, status: "online", mode: MODE });
      return;
    }

    if (request.method === "GET" && url.pathname === "/profile") {
      sendJson(response, profile);
      return;
    }

    if (request.method === "POST" && (url.pathname === "/action" || url.pathname === "/chat")) {
      const payload = await readJson(request);
      const result = await routeAgentRequest(payload, url.pathname);
      sendJson(response, result);
      return;
    }

    sendJson(response, { error: "Not found" }, 404);
  } catch (error) {
    sendJson(response, { error: error.message || "Bridge error" }, 500);
  }
});

server.listen(PORT, HOST, () => {
  console.log(`OneNode Local Agent Bridge listening at http://${HOST}:${PORT}`);
  console.log(`Mode: ${MODE}`);
  if (MODE === "claw") console.log(`Claw base URL: ${CLAW_BASE_URL}`);
  if (MODE === "agent") console.log(`Local Agent base URL: ${LOCAL_AGENT_BASE_URL}`);
});

function setCorsHeaders(response) {
  response.setHeader("Access-Control-Allow-Origin", "*");
  response.setHeader("Access-Control-Allow-Methods", "GET,POST,OPTIONS");
  response.setHeader("Access-Control-Allow-Headers", "Content-Type,Accept");
}

function sendJson(response, payload, statusCode = 200) {
  response.writeHead(statusCode, { "Content-Type": "application/json; charset=utf-8" });
  response.end(JSON.stringify(payload, null, 2));
}

function readJson(request) {
  return new Promise((resolve, reject) => {
    let body = "";
    request.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1_000_000) {
        request.destroy();
        reject(new Error("Payload too large"));
      }
    });
    request.on("end", () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch {
        reject(new Error("Invalid JSON"));
      }
    });
    request.on("error", reject);
  });
}

async function routeAgentRequest(payload, pathname) {
  if (MODE === "agent") return callLocalAgentOrMock(payload, pathname);
  if (MODE === "claw") return callClawOrMock(payload, pathname);
  return mockAction(payload);
}

async function callLocalAgentOrMock(payload, pathname) {
  try {
    const data = await postJsonToAgent(LOCAL_AGENT_BASE_URL, pathname, payload);
    return normalizeActionResponse(data, payload, "local-agent");
  } catch (error) {
    if (pathname === "/chat") {
      try {
        const data = await postJsonToAgent(LOCAL_AGENT_BASE_URL, "/action", payload);
        return normalizeActionResponse(data, payload, "local-agent-action");
      } catch {
        // Fall through to fallback below.
      }
    }
    const fallback = mockAction(payload);
    fallback.reply = `Local Agent is unreachable, so I used bridge fallback. ${fallback.reply}`;
    fallback.message = fallback.reply;
    fallback.adapterWarning = error.message;
    fallback.source = "bridge-fallback";
    return fallback;
  }
}

async function callClawOrMock(payload, pathname) {
  try {
    const data = await postJsonToAgent(CLAW_BASE_URL, pathname, payload);
    return normalizeActionResponse(data, payload, "claw");
  } catch (error) {
    if (pathname === "/chat") {
      try {
        const data = await postJsonToAgent(CLAW_BASE_URL, "/action", payload);
        return normalizeActionResponse(data, payload, "claw-action");
      } catch {
        // Fall through to fallback below.
      }
    }
    const fallback = mockAction(payload);
    fallback.reply = `Claw adapter fallback: ${fallback.reply}`;
    fallback.message = fallback.reply;
    fallback.adapterWarning = error.message;
    fallback.source = "bridge-fallback";
    return fallback;
  }
}

async function postJsonToAgent(baseUrl, pathname, payload) {
  const response = await fetch(`${baseUrl}${pathname}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify(payload),
    signal: AbortSignal.timeout(30_000),
  });
  if (!response.ok) throw new Error(`Agent returned ${response.status}`);
  return response.json();
}

function normalizeActionResponse(data, payload, source) {
  return {
    message: data.reply || data.message || data.result || `Local Agent handled: ${payload.command || "action"}`,
    reply: data.reply || data.message || data.result || `Local Agent handled: ${payload.command || "action"}`,
    suggestedRelations: Array.isArray(data.suggestedRelations) ? data.suggestedRelations : [],
    source,
    raw: data,
  };
}

function mockAction(payload) {
  const command = String(payload.command || "").trim();
  const reply = buildConversationalReply(command, payload);
  const selectedAgent = payload.selectedAgent || {};
  const relationships = Array.isArray(payload.relationships) ? payload.relationships : [];
  const existing = new Set(relationships.map((item) => `${item.agentId}:${item.relation}`));
  const shouldSuggest = shouldSuggestRelations(command);
  const suggestions = shouldSuggest ? [
    {
      agentId: selectedAgent.id || "agent_ledgermind",
      relation: existing.has(`${selectedAgent.id}:trust`) ? "collaborate" : "trust",
      reason: "Selected Agent has strong reputation and matches the current social policy.",
    },
    {
      agentId: "agent_metasage",
      relation: "collaborate",
      reason: "MetaSage is useful for research summaries and social graph introductions.",
    },
    {
      agentId: "agent_nodeguardian",
      relation: "follow",
      reason: "NodeGuardian improves safety checks before deeper collaboration.",
    },
  ].filter((item, index, list) => item.agentId && list.findIndex((candidate) => candidate.agentId === item.agentId) === index) : [];

  return {
    message: reply,
    reply,
    suggestedRelations: suggestions,
    source: "bridge-mock",
    safety: {
      canSignWalletTransactions: false,
      requiresMetaMaskForPayments: true,
      respectsSpendControls: true,
    },
  };
}

function shouldSuggestRelations(command) {
  return /\b(discover|find|collaborat|trust|follow|agent|relationship|connect|关系|发现|协作|关注|信任)\b/i.test(command);
}

function buildConversationalReply(command, payload) {
  const text = command.toLowerCase();
  const selectedName = payload.selectedAgent?.name || "the selected Agent";

  if (!command) {
    return "I am OneNode Local Agent, running on this computer through the local bridge. I can help with Agent relationships, message drafts, wallet safety checks, and research notes.";
  }

  if (/\b(who are you|who are u|who r u|what are you|introduce yourself|你是谁)\b/i.test(command)) {
    return "I am OneNode Local Agent. I run locally on your computer through the bridge at 127.0.0.1:18910. I can suggest Follow, Trust, and Collaborate relationships, draft messages, summarize Agent activity, and check wallet actions before you approve them. I cannot sign wallet transactions or spend funds by myself.";
  }

  if (/\b(hello|hi|hey|你好|哈喽)\b/i.test(command)) {
    return "Hi, I am online. You can ask me to find collaborators, draft an Agent message, summarize your relationship graph, or review a wallet action before you approve it.";
  }

