const state = {
  account: "",
  chainId: "",
  balanceEth: "0.0000",
  agentEndpoint: "http://127.0.0.1:18920",
  agentConnected: false,
  agentProfile: null,
  messages: [
    {
      role: "system",
      text: "连接 MetaMask 后可以读取余额。启动 local-codex-bridge.mjs 后，可以在这里用 Codex 交互模式聊天。",
    },
  ],
};

const els = {
  walletDot: document.querySelector("#walletDot"),
  walletStatus: document.querySelector("#walletStatus"),
  connectWalletBtn: document.querySelector("#connectWalletBtn"),
  refreshBalanceBtn: document.querySelector("#refreshBalanceBtn"),
  walletAddress: document.querySelector("#walletAddress"),
  walletBalance: document.querySelector("#walletBalance"),
  balanceUnit: document.querySelector("#balanceUnit"),
  networkName: document.querySelector("#networkName"),
  chainId: document.querySelector("#chainId"),
  walletProvider: document.querySelector("#walletProvider"),
  agentDot: document.querySelector("#agentDot"),
  agentStatus: document.querySelector("#agentStatus"),
  agentEndpoint: document.querySelector("#agentEndpoint"),
  connectAgentBtn: document.querySelector("#connectAgentBtn"),
  toggleSettingsBtn: document.querySelector("#toggleSettingsBtn"),
  agentSettings: document.querySelector("#agentSettings"),
  agentName: document.querySelector("#agentName"),
  chatLog: document.querySelector("#chatLog"),
  chatForm: document.querySelector("#chatForm"),
  chatInput: document.querySelector("#chatInput"),
  clearChatBtn: document.querySelector("#clearChatBtn"),
  toast: document.querySelector("#toast"),
};

const chainNames = new Map([
  ["0x1", "Ethereum Mainnet"],
  ["0xaa36a7", "Sepolia"],
  ["0x5", "Goerli"],
  ["0x89", "Polygon"],
  ["0xa", "Optimism"],
  ["0xa4b1", "Arbitrum One"],
  ["0x2105", "Base"],
  ["0x38", "BNB Chain"],
]);

function getProvider() {
  return window.ethereum || null;
}

function shortAddress(address) {
  if (!address) return "等待连接";
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function setWalletConnected(connected) {
  els.walletDot.classList.toggle("online", connected);
  els.walletStatus.textContent = connected ? "Wallet online" : "Wallet offline";
}

function setAgentConnected(connected) {
  state.agentConnected = connected;
  els.agentDot.classList.toggle("online", connected);
  els.agentStatus.textContent = connected ? "Codex online" : "Codex offline";
}

function showToast(message) {
  els.toast.textContent = message;
  els.toast.classList.add("show");
  window.clearTimeout(showToast.timer);
  showToast.timer = window.setTimeout(() => els.toast.classList.remove("show"), 2600);
}

async function connectWallet() {
  const provider = getProvider();
  if (!provider) {
    showToast("没有检测到 MetaMask。请在浏览器安装并启用小狐狸钱包。");
    return;
  }

  try {
    const accounts = await provider.request({ method: "eth_requestAccounts" });
    state.account = accounts[0] || "";
    state.chainId = await provider.request({ method: "eth_chainId" });
    await refreshBalance();
    renderWallet();
    showToast("MetaMask 已连接");
  } catch (error) {
    showToast(error.message || "连接 MetaMask 失败");
  }
}

async function refreshBalance() {
  const provider = getProvider();
  if (!provider || !state.account) {
    showToast("请先连接 MetaMask");
    return;
  }

  const [balanceHex, chainId] = await Promise.all([
    provider.request({ method: "eth_getBalance", params: [state.account, "latest"] }),
    provider.request({ method: "eth_chainId" }),
  ]);
  state.chainId = chainId;
  state.balanceEth = formatEther(BigInt(balanceHex));
  renderWallet();
}

function formatEther(wei) {
  const base = 10n ** 18n;
  const whole = wei / base;
  const fraction = wei % base;
  const fractionText = fraction.toString().padStart(18, "0").slice(0, 4);
  return `${whole.toString()}.${fractionText}`;
}

function renderWallet() {
  const connected = Boolean(state.account);
  setWalletConnected(connected);
  els.walletAddress.textContent = connected ? shortAddress(state.account) : "等待连接";
  els.walletBalance.textContent = state.balanceEth;
  els.networkName.textContent = chainNames.get(state.chainId) || (state.chainId ? "Unknown network" : "-");
  els.chainId.textContent = state.chainId || "-";
  els.walletProvider.textContent = getProvider()?.isMetaMask ? "MetaMask" : getProvider() ? "Injected" : "-";
  els.balanceUnit.textContent = nativeUnitForChain(state.chainId);
}

function nativeUnitForChain(chainId) {
  if (chainId === "0x89") return "MATIC";
  if (chainId === "0x38") return "BNB";
  return "ETH";
}

async function connectAgent() {
  state.agentEndpoint = els.agentEndpoint.value.trim().replace(/\/+$/, "");
  if (!state.agentEndpoint) {
    showToast("请输入本地 Agent bridge 地址");
    return;
  }

  try {
    const health = await fetchJson(`${state.agentEndpoint}/health`);
    const profile = await fetchJson(`${state.agentEndpoint}/profile`);
    state.agentProfile = { ...profile, health };
    setAgentConnected(true);
    addMessage("system", `已连接 ${profile.name || "Local Codex Agent"}。`);
    renderAgent();
  } catch (error) {
    setAgentConnected(false);
    showToast(`连接本地 Agent 失败：${error.message}`);
  }
}

async function fetchJson(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

function renderAgent() {
  const profile = state.agentProfile;
  els.agentName.textContent = profile?.name || "Local Codex Agent";
}

function addMessage(role, text) {
  state.messages.push({ role, text });
  renderMessages();
}

function renderMessages() {
  els.chatLog.innerHTML = "";
  state.messages.forEach((message) => {
    const item = document.createElement("article");
    item.className = `message ${message.role}`;
    const label = document.createElement("strong");
    label.textContent = message.role === "user" ? "You" : message.role === "agent" ? "Codex" : "System";
    const body = document.createElement("span");
    body.textContent = message.text;
    item.append(label, body);
    els.chatLog.append(item);
  });
  els.chatLog.scrollTop = els.chatLog.scrollHeight;
}

async function sendChat(event) {
  event.preventDefault();
  const text = els.chatInput.value.trim();
  if (!text) return;

  els.chatInput.value = "";
  addMessage("user", text);

  if (!state.agentConnected) {
    addMessage("system", "请先连接本地 Codex Agent bridge。");
    return;
  }

  try {
    const payload = {
      message: text,
      wallet: {
        address: state.account,
        chainId: state.chainId,
        balance: state.balanceEth,
        unit: nativeUnitForChain(state.chainId),
      },
      history: state.messages.slice(-12),
    };
    const data = await fetchJson(`${state.agentEndpoint}/chat`, {
      method: "POST",
      body: JSON.stringify(payload),
    });
    addMessage("agent", data.reply || data.message || "Codex bridge 没有返回文本。");
  } catch (error) {
    addMessage("system", `发送失败：${error.message}`);
    setAgentConnected(false);
  }
}

function clearChat() {
  state.messages = [{ role: "system", text: "聊天记录已清空。" }];
  renderMessages();
}

function toggleSettings() {
  els.agentSettings.hidden = !els.agentSettings.hidden;
}

function bindWalletEvents() {
  const provider = getProvider();
  if (!provider?.on) return;

  provider.on("accountsChanged", async (accounts) => {
    state.account = accounts[0] || "";
    if (state.account) await refreshBalance();
    renderWallet();
  });

  provider.on("chainChanged", async (chainId) => {
    state.chainId = chainId;
    if (state.account) await refreshBalance();
    renderWallet();
  });
}

els.connectWalletBtn.addEventListener("click", connectWallet);
els.refreshBalanceBtn.addEventListener("click", refreshBalance);
els.connectAgentBtn.addEventListener("click", connectAgent);
els.toggleSettingsBtn.addEventListener("click", toggleSettings);
els.chatForm.addEventListener("submit", sendChat);
els.clearChatBtn.addEventListener("click", clearChat);

bindWalletEvents();
renderWallet();
renderAgent();
renderMessages();

