  min-height: 38px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 11px;
  outline: none;
}

.agent-settings input:focus,
.chat-form input:focus {
  border-color: rgba(25, 135, 84, 0.65);
  box-shadow: 0 0 0 4px rgba(25, 135, 84, 0.11);
}

.chat-log {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 320px;
  max-height: calc(100vh - 390px);
  overflow: auto;
  padding: 16px 2px;
}

.message {
  display: grid;
  gap: 5px;
  max-width: min(720px, 88%);
  border-radius: 8px;
  padding: 12px 13px;
  line-height: 1.55;
}

.message strong {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.message.user {
  align-self: flex-end;
  min-width: 128px;
  background: var(--dark);
  color: #f2fff6;
}

.message.agent {
  align-self: flex-start;
  border: 1px solid var(--line);
  background: #fbfdfb;
}

.message.system {
  align-self: center;
  max-width: 100%;
  background: var(--soft);
  color: var(--muted);
  text-align: center;
}

.chat-form {
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.chat-form input {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 14px;
  outline: none;
}

.toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  max-width: min(420px, calc(100vw - 44px));
  transform: translateY(18px);
  opacity: 0;
  pointer-events: none;
  border-radius: 8px;
  padding: 12px 14px;
  background: var(--dark);
  color: #fff;
  box-shadow: var(--shadow);
  transition: 180ms ease;
}

.toast.show {
  transform: translateY(0);
  opacity: 1;
}

@media (max-width: 760px) {
  .app-shell {
    width: min(100vw - 24px, 980px);
    padding: 12px 0;
  }

  .topbar,
  .wallet-summary,
  .chat-header {
    align-items: stretch;
    flex-direction: column;
  }

  .status-strip,
  .network-line,
  .wallet-actions {
    align-items: flex-start;
    justify-content: flex-start;
  }

  .wallet-summary {
    padding: 18px;
  }

  .button-row,
  .agent-actions,
  .chat-form,
  .agent-settings {
    align-items: stretch;
    flex-direction: column;
  }

  .agent-settings {
    grid-template-columns: 1fr;
  }

  .chat-log {
    max-height: 54vh;
  }

  .message {
    max-width: 100%;
  }
}

