async function connectAgent() {
  state.agentEndpoint = els.agentEndpoint.value.trim().replace(/\/+$/, "");
  if (!state.agentEndpoint) {
    showToast("请输入 Bridge 地址。");
    return;
  }

  try {
    els.connectAgentBtn.disabled = true;
    els.connectAgentBtn.textContent = "连接中";
    const health = await fetchJson(`${state.agentEndpoint}/health`);
    const profile = await fetchJson(`${state.agentEndpoint}/profile`);
    state.agentProfile = { ...profile, health };
    setAgentConnected(true);
    addMessage("system", "Codex 已连接。");
    renderAgent();
  } catch (error) {
    setAgentConnected(false);
    showToast(`连接失败：请确认 local-agent-bridge.mjs 正在运行。`);
  } finally {
    els.connectAgentBtn.disabled = false;
    els.connectAgentBtn.textContent = state.agentConnected ? "重连" : "连接";
  }
}

async function fetchJson(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

async function fetchStream(url, payload, onDelta) {
  const response = await fetch(url, {
    method: "POST",
    headers: {
      Accept: "text/event-stream",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });
  if (!response.ok || !response.body) throw new Error(`HTTP ${response.status}`);

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const events = buffer.split("\n\n");
    buffer = events.pop() || "";

    for (const event of events) {
      const line = event.split("\n").find((item) => item.startsWith("data: "));
      if (!line) continue;
      const data = JSON.parse(line.slice(6));
      if (data.done) return;
      if (data.delta) onDelta(data.delta);
    }
  }
}

function renderAgent() {
  const profile = state.agentProfile;
  els.agentName.textContent = profile?.name || "Local Codex Agent";
}

function addMessage(role, text) {
