  background: var(--accent);
  color: #fff;
  box-shadow: 0 9px 18px rgba(0, 122, 255, 0.22);
}

.primary-button:hover {
  background: var(--accent-strong);
  box-shadow: 0 11px 22px rgba(0, 122, 255, 0.26);
}

.primary-button:active,
.secondary-button:active {
  transform: translateY(1px);
}

.primary-button:disabled,
.secondary-button:disabled {
  cursor: not-allowed;
  opacity: 0.62;
  transform: none;
}

.secondary-button {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.74);
  color: var(--text);
}

.secondary-button:hover {
  border-color: rgba(0, 122, 255, 0.32);
  background: rgba(255, 255, 255, 0.92);
}

.compact {
  min-height: 38px;
  padding: 0 15px;
}

.chat-panel {
  display: grid;
  grid-template-rows: auto auto minmax(130px, 1fr) auto;
  min-height: 0;
  padding: 18px 18px 16px;
}

.chat-header {
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.agent-settings {
  display: grid;
  grid-template-columns: auto minmax(220px, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 12px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.agent-settings[hidden] {
  display: none;
}

.agent-settings input {
  min-height: 38px;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 0 12px;
  background: rgba(255, 255, 255, 0.72);
  outline: none;
}

.agent-settings p {
  grid-column: 2 / -1;
  margin: -2px 0 0;
  color: var(--muted);
  font-size: 12px;
}

.agent-settings input:focus,
.chat-form input:focus {
  border-color: rgba(0, 122, 255, 0.58);
  box-shadow: 0 0 0 4px rgba(0, 122, 255, 0.11);
}

.chat-log {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 150px;
  max-height: calc(100vh - 350px);
  overflow: auto;
  padding: 16px 2px 14px;
}

.message {
  display: grid;
  gap: 5px;
  max-width: min(720px, 88%);
  border-radius: 18px;
  padding: 12px 14px;
  line-height: 1.55;
}

.message strong {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.message.user {
  align-self: flex-end;
  min-width: 128px;
  background: var(--accent);
  color: #ffffff;
}

.message.agent {
  align-self: flex-start;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.76);
}

.message.pending {
  color: var(--muted);
}

.message.system {
  align-self: center;
  max-width: 100%;
  background: var(--accent-soft);
  color: var(--muted);
  text-align: center;
}

.chat-form {
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.chat-form input {
  width: 100%;
  min-height: 50px;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 0 18px;
  background: rgba(255, 255, 255, 0.78);
  outline: none;
}

.chat-form input::placeholder {
  color: #8a968f;
}

.toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  max-width: min(420px, calc(100vw - 44px));
  transform: translateY(18px);
  opacity: 0;
  pointer-events: none;
  border-radius: 18px;
  padding: 12px 14px;
  background: rgba(29, 29, 31, 0.92);
  color: #fff;
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
  transition: 180ms ease;
}

.toast.show {
  transform: translateY(0);
  opacity: 1;
}

