function sleep(ms) {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

async function typeReply(message, text, delayMs = 35) {
  message.text = "";
  message.pending = false;
  renderMessages();

  for (const character of String(text || "")) {
    message.text += character;
    renderMessages();
    await sleep(delayMs);
  }
}

function renderAgent() {
  const profile = state.agentProfile;
  els.agentName.textContent = profile?.name || "Local Codex Agent";
}

function addMessage(role, text) {
  state.messages.push({ role, text });
  renderMessages();
}

function renderMessages() {
  els.chatLog.innerHTML = "";
  state.messages.forEach((message) => {
    const item = document.createElement("article");
    item.className = `message ${message.role}${message.pending ? " pending" : ""}`;
    const label = document.createElement("strong");
    label.textContent = message.role === "user" ? "你" : message.role === "agent" ? "Codex" : "系统";
    const body = document.createElement("span");
    body.textContent = message.text;
    item.append(label, body);
    els.chatLog.append(item);
  });
  els.chatLog.scrollTop = els.chatLog.scrollHeight;
}

async function sendChat(event) {
  event.preventDefault();
  const text = els.chatInput.value.trim();
  if (!text) return;

  els.chatInput.value = "";
  addMessage("user", text);

  if (!state.agentConnected) {
    addMessage("system", "请先连接 Codex。");
    return;
  }

  const pending = { role: "agent", text: "Codex 正在思考...", pending: true };
  state.messages.push(pending);
  renderMessages();
  els.chatSubmitBtn.disabled = true;
  els.chatSubmitBtn.textContent = "回复中";

  try {
    const payload = {
      message: text,
      wallet: {
        address: state.account,
        chainId: state.chainId,
        balance: state.balanceEth,
        unit: nativeUnitForChain(state.chainId),
      },
      history: state.messages.slice(-12),
    };
    const data = await fetchJson(`${state.agentEndpoint}/chat`, {
      method: "POST",
      body: JSON.stringify(payload),
    });
    await typeReply(pending, data.reply || data.message || "Codex 没有返回文本。");
    pending.pending = false;
    renderMessages();
  } catch (error) {
    state.messages = state.messages.filter((message) => message !== pending);
    addMessage("system", `发送失败：${error.message}`);
    setAgentConnected(false);
    els.connectAgentBtn.textContent = "连接";
  } finally {
    els.chatSubmitBtn.disabled = false;
    els.chatSubmitBtn.textContent = "发送";
  }
}

function clearChat() {
  state.messages = [{ role: "system", text: "聊天记录已清空。" }];
  renderMessages();
}

