import http from "node:http";
import { spawn } from "node:child_process";
import { readFile, rm } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";

const HOST = process.env.AGENT_WALLET_HOST || "127.0.0.1";
const PORT = Number(process.env.AGENT_WALLET_PORT || 18920);
const MODE = process.env.AGENT_WALLET_MODE || "mock";
const CODEX_BIN = process.env.CODEX_BIN || "codex";
const CODEX_TIMEOUT_MS = Number(process.env.CODEX_TIMEOUT_MS || 120_000);

const profile = {
  id: "local-codex",
  name: MODE === "codex-cli" ? "Codex CLI Agent" : "Local Mock Agent",
  mode: MODE,
  status: "online",
  skills: ["wallet-summary", "balance-explain", "risk-check", "next-action", "codex-chat"],
};

const server = http.createServer(async (request, response) => {
  setCors(response);

  if (request.method === "OPTIONS") {
    response.writeHead(204);
    response.end();
    return;
  }

  try {
    const url = new URL(request.url || "/", `http://${request.headers.host}`);

    if (request.method === "GET" && url.pathname === "/health") {
      sendJson(response, { ok: true, status: "online", mode: MODE });
      return;
    }

    if (request.method === "GET" && url.pathname === "/profile") {
      sendJson(response, profile);
      return;
    }

    if (request.method === "POST" && url.pathname === "/chat") {
      const payload = await readJson(request);
      sendJson(response, await routeChat(payload));
      return;
    }

    if (request.method === "POST" && url.pathname === "/chat-stream") {
      const payload = await readJson(request);
      const result = await routeChat(payload);
      await sendStream(response, result.reply);
      return;
    }

    sendJson(response, { error: "Not found" }, 404);
  } catch (error) {
    sendJson(response, { error: error.message || "Bridge error" }, 500);
  }
});

server.listen(PORT, HOST, () => {
  console.log(`Agent Wallet 2 Local Codex Bridge listening at http://${HOST}:${PORT}`);
  console.log(`Mode: ${MODE}`);
  if (MODE === "codex-cli") console.log(`Codex binary: ${CODEX_BIN}`);
});

function setCors(response) {
  response.setHeader("Access-Control-Allow-Origin", "*");
  response.setHeader("Access-Control-Allow-Methods", "GET,POST,OPTIONS");
  response.setHeader("Access-Control-Allow-Headers", "Content-Type,Accept");
}

function sendJson(response, payload, status = 200) {
  response.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  response.end(JSON.stringify(payload, null, 2));
}

async function sendStream(response, reply) {
  response.writeHead(200, {
    "Content-Type": "text/event-stream; charset=utf-8",
    "Cache-Control": "no-cache, no-transform",
    Connection: "keep-alive",
    "X-Accel-Buffering": "no",
  });

  for (const chunk of chunkText(reply)) {
    response.write(`data: ${JSON.stringify({ delta: chunk })}\n\n`);
    await delay(42);
  }

  response.write(`data: ${JSON.stringify({ done: true })}\n\n`);
  response.end();
}

function chunkText(text) {
  const chunks = [];
  const normalized = String(text || "");
  for (let index = 0; index < normalized.length; index += 3) {
    chunks.push(normalized.slice(index, index + 3));
  }
  return chunks;
}

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function readJson(request) {
  return new Promise((resolve, reject) => {
    let body = "";
    request.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1_000_000) {
        request.destroy();
        reject(new Error("Payload too large"));
      }
    });
    request.on("end", () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch {
        reject(new Error("Invalid JSON"));
      }
    });
    request.on("error", reject);
  });
}

async function routeChat(payload) {
  if (MODE === "codex-cli") return callCodexCli(payload);
  return buildMockReply(payload);
}

async function callCodexCli(payload) {
  const outputPath = join(tmpdir(), `agentwallet-codex-${Date.now()}-${Math.random().toString(16).slice(2)}.txt`);
  const prompt = buildCodexPrompt(payload);
  const args = [
    "exec",
    "--skip-git-repo-check",
    "--ephemeral",
    "--sandbox",
    "read-only",
    "--color",
    "never",
    "--output-last-message",
    outputPath,
    prompt,
  ];

  const result = await runProcess(CODEX_BIN, args, CODEX_TIMEOUT_MS);
  let reply = "";
  try {
    reply = (await readFile(outputPath, "utf8")).trim();
  } catch {
    reply = "";
  } finally {
    await rm(outputPath, { force: true });
  }

  if (!reply) {
    const stderr = result.stderr.trim().split("\n").slice(-8).join("\n");
    throw new Error(`Codex CLI 没有返回回复。${stderr}`);
  }

  return {
    reply,
    source: "codex-cli",
    raw: {
      exitCode: result.exitCode,
    },
    safety: {
      canReadWalletBalance: true,
      canSignTransactions: false,
      requiresUserWalletConfirmation: true,
    },
  };
}

function runProcess(command, args, timeoutMs) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd: process.cwd(),
      env: {
        ...process.env,
        NO_COLOR: "1",
      },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    const timer = setTimeout(() => {
      child.kill("SIGTERM");
      reject(new Error(`Codex CLI 超时：${Math.round(timeoutMs / 1000)} 秒未返回。`));
    }, timeoutMs);

    child.stdout.on("data", (chunk) => {
      stdout += chunk;
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk;
    });
    child.on("error", (error) => {
      clearTimeout(timer);
      reject(error);
    });
    child.on("close", (exitCode) => {
      clearTimeout(timer);
      if (exitCode === 0) {
        resolve({ exitCode, stdout, stderr });
      } else {
        reject(new Error(`Codex CLI 退出码 ${exitCode}。\n${stderr || stdout}`));
      }
    });
  });
}

function buildCodexPrompt(payload) {
  const wallet = payload.wallet || {};
  const message = String(payload.message || "").trim();
  return [
    "你是 Agent Wallet 页面中的本地 Codex 助手。",
    "请用中文简洁回答。你可以解释钱包余额、链 ID、风险和下一步操作。",
    "不要声称可以签名或转账；所有钱包操作都必须由用户在 MetaMask 中确认。",
    "",
    "钱包上下文：",
    `- 地址：${wallet.address || "未连接"}`,
    `- Chain ID：${wallet.chainId || "未知"}`,
    `- 余额：${wallet.balance || "0.0000"} ${wallet.unit || "ETH"}`,
    "",
    `用户问题：${message || "空消息"}`,
  ].join("\n");
}

function buildMockReply(payload) {
  const message = String(payload.message || "").trim();
  const wallet = payload.wallet || {};
  const hasWallet = Boolean(wallet.address);
  const walletLine = hasWallet
    ? `当前钱包 ${shortAddress(wallet.address)} 在 ${wallet.chainId || "未知链"} 上余额为 ${wallet.balance || "0.0000"} ${wallet.unit || "ETH"}。`
    : "当前还没有连接钱包，我只能先给出通用建议。";

  let reply = `${walletLine}\n\n`;

  if (/余额|balance|多少钱|资产/i.test(message)) {
    reply += "余额读取来自浏览器注入的钱包 provider，本地 Agent 只做解释，不持有私钥，也不会发起签名。";
  } else if (/风险|安全|risk|safe|授权/i.test(message)) {
    reply += "建议先检查当前网络、目标合约地址、授权额度和交易来源。任何转账或授权都应该留在 MetaMask 弹窗里由你确认。";
  } else if (/下一步|建议|next|操作/i.test(message)) {
    reply += "下一步可以先刷新余额，再让 Agent 汇总当前链、余额和目标操作。如果要做交易，先生成只读计划，不直接签名。";
  } else {
    reply += `我按 Codex 交互模式收到你的问题：“${message || "空消息"}”。你可以继续让我分析钱包余额、解释链 ID、做风险检查，或整理下一步操作。`;
  }

  return {
    reply,
    source: "mock-bridge",
    safety: {
      canReadWalletBalance: true,
      canSignTransactions: false,
      requiresUserWalletConfirmation: true,
    },
  };
}

function shortAddress(address) {
  return `${String(address).slice(0, 6)}...${String(address).slice(-4)}`;
}

