  state.agentEndpoint = els.agentEndpoint.value.trim().replace(/\/+$/, "");
  if (!state.agentEndpoint) {
    showToast("请输入 Bridge 地址。");
    return;
  }

  try {
    els.connectAgentBtn.disabled = true;
    els.connectAgentBtn.textContent = "连接中";
    const health = await fetchJson(`${state.agentEndpoint}/health`);
    const profile = await fetchJson(`${state.agentEndpoint}/profile`);
    state.agentProfile = { ...profile, health };
    setAgentConnected(true);
    addMessage("system", profile.mode === "codex-cli" ? "Codex CLI 已连接。" : "本地模拟助手已连接。");
    renderAgent();
  } catch (error) {
    setAgentConnected(false);
    showToast(`连接失败：请确认 local-agent-bridge.mjs 正在运行。`);
  } finally {
    els.connectAgentBtn.disabled = false;
    els.connectAgentBtn.textContent = state.agentConnected ? "重连" : "连接";
  }
}

async function fetchJson(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

async function fetchStream(url, payload, onDelta) {
  const response = await fetch(url, {
    method: "POST",
    headers: {
      Accept: "text/event-stream",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });
  if (!response.ok || !response.body) throw new Error(`HTTP ${response.status}`);

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
let buffer = "";

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const events = buffer.split("\n\n");
    buffer = events.pop() || "";

    for (const event of events) {
      const line = event.split("\n").find((item) => item.startsWith("data: "));
      if (!line) continue;
      const data = JSON.parse(line.slice(6));
      if (data.done) return;
      if (data.delta) onDelta(data.delta);
    }
  }
}

function sleep(ms) {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

async function typeReply(message, text, delayMs = 35) {
  message.text = "";
  message.pending = true;
  renderMessages();

  for (const character of String(text || "")) {
    message.text += character;
    renderMessages();
    await sleep(delayMs);
  }

  message.pending = false;
  renderMessages();
}

function renderAgent() {
  const profile = state.agentProfile;
  els.agentName.textContent = profile ? `${profile.name} · ${profile.mode}` : "Local Codex Agent";
}

function addMessage(role, text) {
  state.messages.push({ role, text });
  renderMessages();
}

function renderMessages() {
  els.chatLog.innerHTML = "";
  state.messages.forEach((message) => {
    const item = document.createElement("article");
    item.className = `message ${message.role}${message.pending ? " pending" : ""}`;
    const label = document.createElement("strong");
    label.textContent = message.role === "user" ? "你" : message.role === "agent" ? "Codex" : "系统";
    const body = document.createElement("span");
    body.textContent = message.text;
    item.append(label, body);
    els.chatLog.append(item);
  });
  els.chatLog.scrollTop = els.chatLog.scrollHeight;
}

async function sendChat(event) {
  event.preventDefault();
  const text = els.chatInput.value.trim();
  if (!text) return;

  els.chatInput.value = "";
  addMessage("user", text);

  if (!state.agentConnected) {
    addMessage("system", "请先连接 Codex。");
    return;
  }

  const pending = { role: "agent", text: "Codex 正在思考...", pending: true };
  state.messages.push(pending);
  renderMessages();
  els.chatSubmitBtn.disabled = true;
  els.chatSubmitBtn.textContent = "回复中";

  try {
    const payload = {
      message: text,
      wallet: {
        address: state.account,
        chainId: state.chainId,
        balance: state.balanceEth,
        unit: nativeUnitForChain(state.chainId),
      },
      history: state.messages.slice(-12),
    };
    const data = await fetchJson(`${state.agentEndpoint}/chat`, {
      method: "POST",
      body: JSON.stringify(payload),
    });
    await typeReply(pending, data.reply || data.message || "Codex 没有返回文本。");
    renderMessages();
  } catch (error) {
    state.messages = state.messages.filter((message) => message !== pending);
    addMessage("system", `发送失败：${error.message}`);
    setAgentConnected(false);
    els.connectAgentBtn.textContent = "连接";
  } finally {
    els.chatSubmitBtn.disabled = false;
    els.chatSubmitBtn.textContent = "发送";
  }
}

function clearChat() {
  state.messages = [{ role: "system", text: "聊天记录已清空。" }];
  renderMessages();
}

function toggleSettings() {
  els.agentSettings.hidden = !els.agentSettings.hidden;
}

function bindWalletEvents() {
  const provider = getProvider();
  if (!provider?.on) return;

  provider.on("accountsChanged", async (accounts) => {
    state.account = accounts[0] || "";
    if (state.account) await refreshBalance();
    renderWallet();
  });

  provider.on("chainChanged", async (chainId) => {
    state.chainId = chainId;
    if (state.account) await refreshBalance();
    renderWallet();
  });
}

els.connectWalletBtn.addEventListener("click", connectWallet);
els.refreshBalanceBtn.addEventListener("click", refreshBalance);
els.connectAgentBtn.addEventListener("click", connectAgent);
els.toggleSettingsBtn.addEventListener("click", toggleSettings);
els.chatForm.addEventListener("submit", sendChat);
els.clearChatBtn.addEventListener("click", clearChat);

bindWalletEvents();
renderWallet();
renderAgent();
renderMessages();

